/* Obrazki skrzynek (ikonka widoczna w nagłówku panelu otwierania),
   kluczem jest CASE_NAME użyty w danym pliku skrzynki. */
const CASE_IMAGES = {
  "Dirt Case": "dirt_case.png",
  "Iron Case": "iron_case.png",
  "Gold Case": "gold_case.png",
  "Ultra Case": "ultra_case.png",
  "Snow Case": "snow_case.png",
  "Neon Case": "neon_case.png",
  "Waste Case": "waste_case.png",
  "Jungle Case": "case_jungle.PNG",
  "Diamond Case": "case_diamond.PNG",
  "Sand Case": "case_sand.PNG",
  "Poland Case": "case_poland.PNG",
  "Cosmos Case": "case_cosmos.PNG",
  "Flower Sticker": "sticker_flower.PNG",
  "Ice Sticker": "sticker_ice.PNG",
  "Slime Case": "case_slime.PNG",
  "Water Case": "case_water.PNG",
  "Knifes Case": "case_knifes.PNG",
  "Web Case": "case_web.PNG",
  "Noir Case": "case_noir.PNG",
  "Robot Sticker": "sticker_robot.PNG",
  "Lava Case": "lava_case.png",
  "Devil Case": "case_devil.PNG",
  "Angel Case": "case_angel.PNG",
};

/* Zwraca link do obrazka danego przedmiotu na podstawie broni, skina i wear. */
function getSkinImage(it){
  return SKIN_IMAGES[`${it.weapon}|${it.skin}|${it.wear}`] || "";
}

/* Zwraca link do obrazka skrzynki na podstawie jej nazwy. */
function getCaseImage(caseName){
  return CASE_IMAGES[caseName] || "";
}